"""Decoder tests against real HLS streams generated by ffmpeg.

Everything else in this project reasons about a stream from the outside. These
tests build the three cases that defeat an outside check and confirm a decoder
tells them apart: a normal stream, one whose every frame is black, and a
container with sound and no picture.

Skipped when ffmpeg is absent, because the gate itself is skipped then too.
"""
import http.server
import shutil
import socketserver
import subprocess
import sys
import tempfile
import threading
import unittest
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))

from src.validators import decode as D

HAVE_FFMPEG = D.available()


def _make(dirpath: Path, name: str, source: str, audio: bool = False) -> None:
    codec = ["-c:a", "aac"] if audio else ["-c:v", "libx264", "-preset", "ultrafast",
                                           "-g", "25"]
    subprocess.run(
        ["ffmpeg", "-hide_banner", "-loglevel", "error", "-f", "lavfi", "-i", source,
         *codec, "-f", "hls", "-hls_time", "2", "-hls_playlist_type", "vod",
         "-hls_segment_filename", str(dirpath / f"{name}%d.ts"),
         str(dirpath / f"{name}.m3u8")],
        check=True, stdin=subprocess.DEVNULL, capture_output=True, timeout=120)


@unittest.skipUnless(HAVE_FFMPEG, "ffmpeg not installed")
class TestDecodeAgainstRealStreams(unittest.TestCase):
    port = 0
    httpd = None
    tmp = None

    @classmethod
    def setUpClass(cls):
        cls.tmp = Path(tempfile.mkdtemp())
        _make(cls.tmp, "ok", "testsrc2=size=640x360:rate=25:duration=8")
        _make(cls.tmp, "black", "color=c=black:size=640x360:rate=25:duration=8")
        _make(cls.tmp, "audio", "sine=frequency=440:duration=8", audio=True)

        root = str(cls.tmp)

        class Handler(http.server.SimpleHTTPRequestHandler):
            def __init__(self, *a, **kw):
                super().__init__(*a, directory=root, **kw)

            def log_message(self, *a):
                pass

        cls.httpd = socketserver.TCPServer(("127.0.0.1", 0), Handler)
        cls.port = cls.httpd.server_address[1]
        threading.Thread(target=cls.httpd.serve_forever, daemon=True).start()

    @classmethod
    def tearDownClass(cls):
        if cls.httpd:
            cls.httpd.shutdown()
            cls.httpd.server_close()
        if cls.tmp:
            shutil.rmtree(cls.tmp, ignore_errors=True)

    def _decode(self, name):
        return D.decode(f"http://127.0.0.1:{self.port}/{name}.m3u8",
                        seconds=4, timeout=60)

    def test_a_normal_stream_is_confirmed_playable(self):
        r = self._decode("ok")
        self.assertTrue(r.measured)
        self.assertTrue(r.has_video)
        self.assertEqual(r.codec, "h264")
        self.assertEqual((r.width, r.height), (640, 360))
        self.assertGreater(r.frames, 20)
        self.assertLess(r.black_fraction, 0.2)
        self.assertEqual(D.verdict(r), "", "a working stream must pass silently")

    def test_an_all_black_stream_is_caught(self):
        """The decoder's whole reason for existing: this stream has a valid
        manifest, real segments and a decodable h264 track, and shows nothing."""
        r = self._decode("black")
        self.assertTrue(r.has_video, "it does decode - that is the point")
        self.assertGreater(r.frames, 20)
        self.assertGreater(r.black_fraction, 0.9)
        self.assertIn("black", D.verdict(r))

    def test_an_audio_only_container_is_caught(self):
        r = self._decode("audio")
        self.assertFalse(r.has_video)
        self.assertTrue(r.has_audio)
        self.assertIn("no video stream", D.verdict(r))

    def test_the_measured_size_comes_from_the_decoder(self):
        """A manifest's RESOLUTION is a claim; this is a measurement."""
        r = self._decode("ok")
        self.assertEqual(r.width, 640)
        self.assertEqual(r.height, 360)


class TestDecodeIsAlwaysOptional(unittest.TestCase):
    """A decode that could not be taken is never evidence against a channel."""

    def test_an_unmeasured_result_withholds_nothing(self):
        self.assertEqual(D.verdict(D.DecodeResult(measured=False)), "")

    def test_a_missing_binary_reports_rather_than_raises(self):
        r = D.describe("https://example.invalid/x.m3u8")
        self.assertIsInstance(r, D.DecodeResult)

    def test_a_dark_scene_is_not_a_dead_feed(self):
        """A film can be dark for a while. Only an essentially entirely black
        decode counts, and the threshold is deliberately near the top."""
        r = D.DecodeResult(measured=True, has_video=True, frames=100,
                           decoded_seconds=4.0, black_seconds=2.4)
        self.assertEqual(D.verdict(r), "", "60% black is a film, not a dead feed")

    def test_a_stalling_feed_is_caught_by_the_frame_floor(self):
        r = D.DecodeResult(measured=True, has_video=True, frames=2,
                           decoded_seconds=4.0)
        self.assertIn("stalling", D.verdict(r))

    def test_the_protocol_whitelist_excludes_the_filesystem(self):
        """ffmpeg is handed URLs from an aggregator. A crafted playlist must not
        be able to read the runner's disk."""
        self.assertNotIn("file", D._PROTOCOLS.split(","))
        self.assertNotIn("concat", D._PROTOCOLS.split(","))
        self.assertNotIn("pipe", D._PROTOCOLS.split(","))
